                      variant="outline"
                      render={<Link href={board.href} />}
                    >
                      Ouvrir
                    </Button>
                  ) : (
                    <Button size="sm" variant="outline" disabled>
                      Bientôt disponible
                    </Button>
                  )}
                </CardContent>
              </Card>
            );
          })}
